import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 17
    reader = csv.reader(io.StringIO(raw_csv.lstrip("\ufeff"), newline=""), delimiter=";", quotechar='"', strict=False)
    records = [row for row in reader if row]

    if not records:
        return {"columns": [], "rows": []}

    header_index = 0
    header_markers = re.compile(
        r"\b(name|status|runtime|value|limit|objective|time|column|date|type|size)\b",
        re.IGNORECASE,
    )
    for i, row in enumerate(records):
        if len(row) >= expected_width - 1 and header_markers.search(" ".join(row)):
            header_index = i
            break

    columns = list(records[header_index])
    data = records[header_index + 1:]
    width = max(expected_width, len(columns), max((len(row) for row in data), default=0))

    while len(columns) < width:
        columns.append(f"Column{len(columns) + 1}")

    rows = []
    for record in data:
        row = list(record)
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
